<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,ArrowRight,FileText,Upload,BookOpen,Users,MapPin,Flag,Check,LoaderCircle,RefreshCw,ChevronRight} from 'lucide-vue-next'
import {worldApi} from './api'
import PageHeader from '../workspace/PageHeader.vue'
import Sheet from '../components/Sheet.vue'
import {newKey} from '../api'
import {storyPath} from '../api/stories'
import {useRequestScope} from '../platform/request-scope'
interface Entity{id:string;name:string;type:string;description:string;evidence?:{blockId:string;quote:string}[]}
interface Scene{id:string;title:string;summary:string;placeId:string;characterIds:string[];sourceBlockIds:string[]}
interface Objective{id:string;title:string;description:string;requires:string[];checks:{kind:string;entityId:string;placeId?:string;itemId?:string;loreId?:string;toId?:string;field?:string;value?:unknown}[];sourceBlockIds:string[]}
interface Script{synopsis:string;definition:{entities:Entity[];lore:{id:string;title:string}[]};routes:Record<string,string[]>;scenes:Scene[];objectives:Objective[];endings:{id:string;title:string;description:string}[];recommendedCharacterId:string;opening:string}
interface View{worldId:string;name:string;worldVersion:number;status:string;worldStatus:string;hasSaves?:boolean;reviewIssues?:string[];blockCount:number;processedBlocks:number;sourceCharacters:number;receivedCharacters?:number;value?:Script;source:{blocks:{blockId:string;text:string}[]};provenance:{sourceUrl?:string;author?:string;license?:string};task?:{id:string;state:string;phase:string;errorCode?:string}}
const route=useRoute(),router=useRouter(),capture=useRequestScope(),mode=ref<'sample'|'text'>('sample'),title=ref('蓝宝石案'),text=ref(''),fileName=ref(''),view=ref<View|null>(null),value=ref<Script|null>(null),tab=ref('scenes'),busy=ref(false),error=ref(''),raw=ref(''),rawEditing=ref(false),sourceBlock=ref(''),file=ref<HTMLInputElement>()
const samples=ref<{id:string;title:string;description:string;author:string;sourceUrl:string}[]>([]),sampleId=ref('blue-carbuncle')
const sample=computed(()=>samples.value.find(s=>s.id===sampleId.value)||{id:'blue-carbuncle',title:'蓝宝石案',description:'从一顶旧帽、一只圣诞鹅，追索失窃宝石背后的真相。',author:'阿瑟·柯南·道尔',sourceUrl:'https://www.gutenberg.org/ebooks/1661'})
function selectSample(){title.value=sample.value.title}
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const working=computed(()=>busy.value||!!view.value?.task&&!['succeeded','failed','cancelled'].includes(view.value.task.state)),ready=computed(()=>!!value.value&&['review','published'].includes(view.value?.status||'')),entities=computed(()=>value.value?.definition.entities||[])
const tabs=[{id:'scenes',label:'场景',icon:BookOpen},{id:'characters',label:'人物',icon:Users},{id:'places',label:'地点',icon:MapPin},{id:'objectives',label:'任务与结局',icon:Flag},{id:'source',label:'原文',icon:FileText}]
function label(id?:string){if(!id)return '';return entities.value.find(e=>e.id===id)?.name||value.value?.definition.lore.find(e=>e.id===id)?.title||id}
async function evidence(ids:string[]){sourceBlock.value=ids[0]||'';tab.value='source';await nextTick();document.getElementById(sourceBlock.value)?.scrollIntoView({block:'center'})}
const previewing=ref(false),savedNotice=ref('')
async function saveDraft(){if(!view.value||!value.value||working.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await worldApi<{worldVersion:number}>('/worlds/'+view.value.worldId+'/script/draft',{method:'PUT',key:newKey(),body:{expectedVersion:view.value.worldVersion,value:value.value}});if(scope.valid()){view.value={...view.value,worldVersion:result.worldVersion};savedNotice.value='草稿已保存，刷新后可以继续校对。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
function exportDraft(){if(!value.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(value.value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='story-draft.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function reset(){savedNotice.value='';previewing.value=false;clearTimeout(timer);value.value=null;view.value=null;error.value=''}
async function load(id:string){const scope=capture();try{const next=await worldApi<View>('/worlds/'+id+'/script');if(!scope.valid()||disposed)return;view.value=next;if(next.value&&!value.value)value.value=structuredClone(next.value);if(next.task&&next.task.state==='failed')error.value='这次拆解未完成，原文和已处理内容仍保留。可以重试。';if(next.task&&!['succeeded','failed','cancelled'].includes(next.task.state))timer=setTimeout(()=>void load(id),1500)}catch(e){if(scope.valid()&&!disposed){error.value=(e as Error).message;timer=setTimeout(()=>void load(id),3000)}}}
async function preparedSample(){if(working.value)return;busy.value=true;error.value='';try{const result=await worldApi<{worldId:string}>('/scripts/samples/blue-carbuncle/prepared',{method:'POST',key:newKey(),body:{}});await router.replace({path:'/worlds/scripts',query:{world:result.worldId}});await load(result.worldId)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function create(){if(working.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await worldApi<{worldId:string}>('/scripts',{method:'POST',key:newKey(),body:{title:title.value,text:mode.value==='text'?text.value:'',sampleId:mode.value==='sample'?sampleId.value:null,genre:'mystery'}});if(!scope.valid())return;await router.replace({path:'/worlds/scripts',query:{world:result.worldId}});await load(result.worldId)}catch(e){if(scope.valid())error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const selected=(event.target as HTMLInputElement).files?.[0];if(!selected)return;if(selected.size>4000000){error.value='文件过大，请按完整分卷上传。';return}const data=await selected.arrayBuffer();try{text.value=new TextDecoder('utf-8',{fatal:true}).decode(data)}catch{text.value=new TextDecoder('gb18030').decode(data)}fileName.value=selected.name;title.value=selected.name.replace(/\.[^.]+$/,'');mode.value='text';error.value=''}
async function retry(){if(!view.value||working.value)return;busy.value=true;error.value='';try{await worldApi('/worlds/'+view.value.worldId+'/script/retry',{method:'POST',key:newKey(),body:{}});value.value=null;await load(view.value.worldId)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function editJson(){raw.value=JSON.stringify(value.value,null,2);rawEditing.value=true}
function saveJson(){try{const parsed=JSON.parse(raw.value);if(!parsed.definition||!Array.isArray(parsed.scenes)||!Array.isArray(parsed.objectives))throw new Error();value.value=parsed;rawEditing.value=false;error.value=''}catch{error.value='JSON结构不完整，请检查人物、场景和任务。'}}
async function revision(){if(!view.value||working.value)return;busy.value=true;error.value='';try{const next=await worldApi<{worldId:string}>('/worlds/'+view.value.worldId+'/script/revision',{method:'POST',key:newKey(),body:{}});reset();await router.replace({path:'/worlds/scripts',query:{world:next.worldId}});await load(next.worldId)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function publish(){if(view.value?.hasSaves){await revision();return}if(!view.value||!value.value||working.value)return;busy.value=true;error.value='';try{await worldApi('/worlds/'+view.value.worldId+'/script/publish',{method:'POST',key:newKey(),body:{expectedVersion:view.value.worldVersion,value:value.value}});await router.push(storyPath('world',view.value.worldId))}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(route.query.world)void load(String(route.query.world));else void worldApi<{items:typeof samples.value}>('/scripts/samples').then(r=>{if(!disposed)samples.value=r.items}).catch(()=>{})})
onUnmounted(()=>{disposed=true;clearTimeout(timer)})
</script>

<template>
  <div class="script-page">
    <header class="script-header"><RouterLink to="/worlds/new" class="inline-link">从原创模板创作</RouterLink><RouterLink to="/worlds" class="inline-link"><ArrowLeft :size="18"/>世界</RouterLink><RouterLink v-if="view" to="/worlds/scripts" class="inline-link" @click="reset">新的拆解</RouterLink></header>
    <PageHeader :title="view?.name||'创作工作台'" eyebrow="故事创作" description="导入故事，校对设定，保存后再进入世界。"><template v-if="ready"><button :disabled="working||rawEditing" @click="previewing=true">预览开局</button><button :disabled="working||rawEditing" @click="exportDraft">导出校对稿</button><button v-if="view?.status==='review'&&!view.hasSaves" class="primary" :disabled="working||rawEditing" @click="saveDraft">保存草稿</button><button v-else :disabled="working" @click="revision">制作新版本</button></template></PageHeader><nav class="creator-steps" aria-label="创作进度"><span :data-current="!view">1 · 导入故事</span><span :data-current="!!view&&view.status!=='published'">2 · 校对设定</span><span :data-current="view?.status==='published'">3 · 开始体验</span></nav><p v-if="savedNotice" class="product-hint" role="status">{{savedNotice}}</p>
    <p v-if="error" class="error" role="alert">{{error}}</p>
    <template v-if="!view">
      <div class="script-import-layout"><section class="script-card script-import"><div class="script-tabs" aria-label="故事来源"><button :class="{active:mode==='sample'}" @click="mode='sample';selectSample()">完整示例</button><button :class="{active:mode==='text'}" @click="mode='text';title=''">我的文本</button></div>
        <template v-if="mode==='sample'"><label class="script-field">完整作品<select v-model="sampleId" aria-label="选择完整示例作品" @change="selectSample"><option v-for="s in samples.length?samples:[sample]" :key="s.id" :value="s.id">{{s.title}}</option></select></label><div class="script-book"><span>SHERLOCK HOLMES</span><BookOpen :size="62"/><h2>{{sample.title}}</h2><small>{{sample.author}} · {{sampleId==='hound-baskervilles'?'完整长篇 · 15章':'完整短篇'}}</small></div><p class="script-book-copy">{{sample.description}}</p><a :href="sample.sourceUrl" target="_blank" rel="noopener noreferrer" class="inline-link">公版原文 · Project Gutenberg <ChevronRight :size="15"/></a></template>
        <template v-else><button class="script-upload" @click="file?.click()"><Upload :size="30"/><strong>{{fileName||'上传完整故事'}}</strong><span>TXT / Markdown · UTF-8、GB18030</span></button><input ref="file" class="script-hidden-file" type="file" accept=".txt,.md,text/plain,text/markdown" aria-label="上传剧本文件" @change="upload"><label class="script-field">作品名称<input v-model="title" maxlength="160" placeholder="给这个世界一个名字"></label><label class="script-field">完整文本<textarea v-model="text" maxlength="1000000" rows="14" placeholder="也可以在这里粘贴全文"></textarea></label><small>{{text.length.toLocaleString()}} 字符</small></template>
      </section><aside class="script-import-aside"><span class="eyebrow">从原文到可玩的故事</span><h2>不只是一份摘要</h2><div v-for="(step,i) in [{title:'人物与地点',copy:'身份、动机、物品与相互连接的道路。'},{title:'场景与线索',copy:'剧情的来龙去脉，每一处都能回看原文。'},{title:'任务与结局',copy:'调查、交付、作出选择，让故事有真正的终点。'}]" :key="i" class="script-import-step"><span>{{String(i+1).padStart(2,'0')}}</span><div><h3>{{step.title}}</h3><p>{{step.copy}}</p></div></div><button v-if="mode==='sample'&&sampleId==='blue-carbuncle'" :disabled="working" @click="preparedSample">使用已校对版本 · 包含三条善后</button><button class="primary script-primary" :disabled="working||mode==='text'&&text.trim().length<100" @click="create"><LoaderCircle v-if="working" :size="19" class="script-spin"/><FileText v-else :size="19"/>{{working?'正在开始拆解…':'开始拆解'}}<ArrowRight :size="18"/></button></aside></div>
    </template>
    <section v-else-if="!ready" class="script-card script-progress" aria-live="polite"><LoaderCircle v-if="working" class="script-spin" :size="35"/><FileText v-else :size="35"/><h2>{{working?'正在读懂整个故事':'拆解已保留'}}</h2><p>{{view.sourceCharacters.toLocaleString()}} 字符 · {{view.blockCount}} 段原文<span v-if="view.receivedCharacters"> · 已收到 {{view.receivedCharacters.toLocaleString()}} 字符</span></p><progress :value="view.processedBlocks" :max="view.blockCount" aria-label="拆解进度"></progress><button v-if="!working" class="primary" @click="retry"><RefreshCw :size="17"/>重新拆解</button><details v-if="!working"><summary>查看原文</summary><pre class="script-source">{{view.source.blocks.map(b=>b.text).join('\n\n')}}</pre></details></section>
    <template v-else-if="value">
      <section v-if="view.reviewIssues?.length" class="script-card" role="status"><strong>开场需要校对</strong><p v-for="issue in view.reviewIssues" :key="issue">{{issue}}</p></section>
      <section class="script-card script-synopsis"><div><small class="eyebrow">完整拆解</small><p>{{value.synopsis}}</p><a v-if="view.provenance.sourceUrl" :href="view.provenance.sourceUrl" target="_blank" rel="noopener noreferrer" class="inline-link">{{view.provenance.author}} · 原文来源<ChevronRight :size="14"/></a></div><div class="script-totals"><strong>{{value.scenes.length}}<small>场景</small></strong><strong>{{entities.filter(e=>e.type==='character').length}}<small>人物</small></strong><strong>{{value.objectives.length}}<small>任务</small></strong></div></section>
      <nav class="script-review-tabs" aria-label="拆解内容"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id"><component :is="t.icon" :size="17"/>{{t.label}}</button></nav>
      <section v-if="tab==='scenes'" class="script-scene-list"><article v-for="(scene,i) in value.scenes" :key="scene.id" class="script-card script-scene-card"><span class="script-scene-index">{{String(i+1).padStart(2,'0')}}</span><div><input v-model="scene.title" class="script-edit-title" aria-label="场景标题"><div class="script-scene-meta"><span><MapPin :size="14"/>{{label(scene.placeId)}}</span><span><Users :size="14"/>{{scene.characterIds.map(label).join('、')}}</span></div><textarea v-model="scene.summary" class="script-edit-copy" rows="3" aria-label="场景内容"></textarea><button class="script-evidence" @click="evidence(scene.sourceBlockIds)">查看原文 <ChevronRight :size="14"/></button></div></article></section>
      <div v-else-if="tab==='characters'||tab==='places'" class="script-entity-grid"><article v-for="entity in entities.filter(e=>e.type===(tab==='characters'?'character':'place'))" :key="entity.id" class="script-card script-entity-card"><span class="script-entity-monogram">{{entity.name.slice(0,1)}}</span><h3>{{entity.name}}</h3><textarea v-model="entity.description" rows="5" aria-label="设定描述"></textarea><div v-if="tab==='places'" class="script-neighbors"><span v-for="id in value.routes[entity.id]" :key="id"><ArrowRight :size="13"/>{{label(id)}}</span></div><button v-if="entity.evidence?.length" class="script-evidence" @click="evidence(entity.evidence.map(e=>e.blockId))">原文依据<ChevronRight :size="14"/></button></article></div>
      <section v-else-if="tab==='objectives'" class="script-objectives"><article v-for="(objective,i) in value.objectives" :key="objective.id" class="script-card"><div class="script-objective-heading"><span>{{String(i+1).padStart(2,'0')}}</span><input v-model="objective.title" class="script-edit-title" aria-label="任务标题"/></div><textarea v-model="objective.description" class="script-edit-copy" rows="2" aria-label="任务说明"></textarea><div class="script-checks"><span v-for="(check,j) in objective.checks" :key="j"><Check :size="14"/>{{({visit:'抵达',inventory:'持有',acquired:'曾获得',knowledge:'查明',transfer:'交付',field:'作出决定'} as Record<string,string>)[check.kind]}} {{label(check.placeId||check.itemId||check.loreId)||check.value}}<template v-if="check.toId"> → {{label(check.toId)}}</template></span></div></article><article v-for="ending in value.endings" :key="ending.id" class="script-card script-ending"><Flag :size="24"/><h3>{{ending.title}}</h3><p>{{ending.description}}</p></article></section>
      <section v-else class="script-card script-source-panel"><article v-for="block in view.source.blocks" :key="block.blockId" :class="{selected:sourceBlock===block.blockId}" :id="block.blockId"><small>{{block.blockId}}</small><p>{{block.text}}</p></article></section>
      <details class="script-advanced"><summary>编辑完整结构</summary><button v-if="!rawEditing" @click="editJson">打开结构编辑器</button><template v-else><label class="script-field">剧本 JSON<textarea v-model="raw" rows="20" spellcheck="false"></textarea></label><button @click="rawEditing=false">取消</button><button class="primary" @click="saveJson">应用编辑</button></template></details>
      <footer class="script-publish-bar"><span><Check :size="17"/>原文已完整保留</span><button class="primary" :disabled="working||rawEditing" @click="publish">{{view.hasSaves?'制作新版本':view.status==='published'?'进入世界':'创建可玩的世界'}}<ArrowRight :size="18"/></button></footer>
    </template>
  <Sheet v-if="previewing&&value" title="开局预览" @close="previewing=false"><span class="capability-badge" data-status="ready">预览不调用模型</span><h2>{{view?.name}}</h2><p class="creator-preview">{{value.opening}}</p><h3>推荐身份</h3><p>{{label(value.recommendedCharacterId)}}</p><h3>内容规模</h3><p>{{value.scenes.length}} 个场景 · {{entities.filter(e=>e.type==='character').length}} 位人物 · {{value.objectives.length}} 项任务 · {{value.endings.length}} 条结局</p><p class="product-note">开始体验后，行动与 AI 生成按模型通道的额度执行。公开作品需在作者工作台保存配置并提交审核；当前私人作品仅自己可见。</p></Sheet>
  </div>
</template>

<style scoped>
.script-page{width:min(1360px,100%);margin:auto;padding:24px 28px 100px}.script-header{display:flex;justify-content:space-between;margin-bottom:36px}.script-title{display:flex;align-items:center;gap:18px;margin-bottom:30px}.script-title h1{font-family:var(--font-serif,serif);font-size:36px;margin:4px 0 0}.script-title small{color:var(--muted,#817a6d);letter-spacing:.12em}.script-title-icon{padding:15px;border:1px solid var(--border,#e6ddce);border-radius:18px;color:var(--accent,#ad5830);background:var(--surface,#fffaf2)}.script-source-count{margin-left:auto;font-size:13px;color:var(--muted,#817a6d)}.script-card{background:var(--surface,#fffdf7);border:1px solid var(--border,#e6ddce);border-radius:18px;padding:28px}.script-import-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(300px,.85fr);gap:48px}.script-tabs{display:flex;background:var(--bg,#f5eee1);border-radius:12px;padding:5px;margin-bottom:28px}.script-tabs button{flex:1;border:0;background:transparent;min-height:44px}.script-tabs button.active{background:var(--surface,#fffdf7);box-shadow:0 2px 8px #4a38200b;border-radius:9px;color:var(--accent,#ad5830)}.script-book{width:220px;min-height:290px;margin:32px auto;background:#344b46;color:#f7ecd5;padding:28px 20px;display:flex;align-items:center;flex-direction:column;justify-content:space-around;border-radius:4px 12px 12px 4px;box-shadow:8px 10px 0 #e0d5bf,0 16px 30px #4a382018}.script-book>span{font-size:10px;letter-spacing:.22em}.script-book h2{font:28px var(--font-serif,serif);margin:0}.script-book small{color:#e1d7c3;font-size:11px}.script-book-copy{margin-top:38px;line-height:1.8}.script-import-aside{padding:50px 6px}.script-import-aside h2{font-size:30px;margin:12px 0 36px;font-family:var(--font-serif,serif)}.script-import-step{display:flex;gap:18px;margin:26px 0}.script-import-step>span{font:22px var(--font-serif,serif);color:var(--accent,#ad5830)}.script-import-step h3{margin:0 0 8px;font-size:16px}.script-import-step p{margin:0;line-height:1.8;color:var(--muted,#817a6d);font-size:14px}.script-primary{margin-top:30px;min-height:50px;display:flex;align-items:center;justify-content:center;gap:12px;width:100%}.script-upload{width:100%;padding:34px 12px;display:flex;flex-direction:column;align-items:center;gap:12px;border-style:dashed;min-height:150px}.script-upload span{font-size:12px;color:var(--muted,#817a6d)}.script-hidden-file{position:absolute;width:1px;height:1px;opacity:0}.script-field{display:flex;flex-direction:column;gap:9px;margin-top:22px;font-size:14px}.script-field textarea,.script-field input{width:100%;resize:vertical}.script-progress{max-width:720px;margin:60px auto;text-align:center;padding:56px}.script-progress p{color:var(--muted,#817a6d)}.script-progress progress{display:block;width:100%;height:5px;margin:28px 0}.script-spin{animation:spin 1.2s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.script-synopsis{display:flex;align-items:center;gap:35px}.script-synopsis p{font-size:15px;line-height:1.9;max-width:900px}.script-totals{display:flex;gap:24px;margin-left:auto}.script-totals strong{font:29px var(--font-serif,serif);text-align:center}.script-totals small{display:block;font:12px sans-serif;color:var(--muted,#817a6d);margin-top:10px}.script-review-tabs{display:flex;gap:7px;margin:28px 0 22px;flex-wrap:wrap}.script-review-tabs button{display:flex;align-items:center;gap:7px;min-height:44px;background:transparent;border-color:transparent}.script-review-tabs .active{background:var(--surface,#fffdf7);border-color:var(--border,#e6ddce);color:var(--accent,#ad5830)}.script-scene-list{display:flex;flex-direction:column;gap:18px}.script-scene-card{display:grid;grid-template-columns:48px minmax(0,1fr);gap:16px}.script-scene-index{font:23px var(--font-serif,serif);color:var(--accent,#ad5830);padding-top:10px}.script-edit-title{font-size:19px;font-weight:600;width:100%;border-color:transparent!important;background:transparent!important;padding:8px 0!important}.script-scene-meta