:anywhere}.script-advanced{margin:25px 0;color:var(--muted,#817a6d);font-size:13px}.script-advanced summary{cursor:pointer;min-height:44px;padding:12px 0}.script-publish-bar{position:sticky;bottom:0;z-index:4;display:flex;justify-content:space-between;align-items:center;gap:16px;margin-top:25px;padding:18px 22px;background:var(--surface,#fffdf7);border:1px solid var(--border,#e6ddce);border-radius:14px;box-shadow:0 -8px 30px #4a382008}.script-publish-bar>span{display:flex;align-items:center;gap:7px;color:var(--muted,#817a6d);font-size:13px}.script-publish-bar button{min-height:46px;display:flex;align-items:center;gap:12px}@media(min-width:1800px){.script-page{width:min(1600px,100%)}}@media(max-width:900px){.script-import-layout{grid-template-columns:1fr;gap:15px}.script-import-aside{padding:20px 4px}.script-entity-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.script-synopsis{align-items:flex-start;flex-direction:column}.script-totals{margin-left:0}.script-objectives{grid-template-columns:1fr}}@media(max-width:560px){.script-page{padding:20px 12px 80px}.script-title h1{font-size:28px}.script-card{padding:20px}.script-entity-grid{grid-template-columns:1fr}.script-source-count{display:none}.script-scene-card{grid-template-columns:30px minmax(0,1fr);gap:8px}.script-publish-bar>span{font-size:11px}}@media(prefers-reduced-motion:reduce){.script-spin{animation:none}}
